"""November 11 editorial review of original v0.9.23 public definitions."""
import re

SOURCE = 'https://pokebonk.com/assets/defineProperty-BtunVr2f-mwaj5w8h.js'
NEWS = 'https://api.pokebonk.com/news'
# Original v0.9.23 image sources, downloaded and visually inspected November 11.
MEDIA = {'expedition.webp': 'https://pokebonk.com/assets/ui/events/exp.jpg?v=2uc6Pkg7',
         'archive-icon.png': 'https://pokebonk.com/assets/items/everstone.png?v=O7geURXZ'}


def apply_november(ctx):
    pages = ctx['PAGES']
    section, ext = ctx['section'], ctx['ext']
    support = '<p>Checked November 11, 2026 against original v0.9.23 / mwaj5w8h. ' + ext(SOURCE, 'Original release history and definitions') + ' and ' + ext(NEWS, 'Charcher’s announcements') + '. Source-based instructions. Extraction, recovery, installation and competitive results were not playtested.</p>'

    def add(slug, anchor, heading, body):
        page = pages['/pokebonk/' + slug + '/']
        page['html'] = re.sub(r'(<article\b[^>]*>)', lambda m: m[1] + section(anchor, heading, body + support), page['html'], count=1)
        page['html'] = page['html'].replace('<strong>On this page</strong>', '<strong>On this page</strong><a href="#' + anchor + '">' + heading + '</a>', 1)

    add('builds', 'rental', 'Copy a current build and check its requirements',
        '<p>Open <strong>Builds → Rental</strong>, or <strong>Rent</strong> inside a Pokémon’s Build Plan. Since v0.9.17 this lists leading builds with creator, rank and missing requirements. Choose the same Pokémon and compare the displayed mode and requirements before copying. The one-click copy feature arrived in v0.9.15.</p>'
        '<ol><li>Inspect the creator and ranking context. A placement supplies a candidate to inspect.</li><li>Copy the plan, then read its locked, archived and missing-requirement markers before starting.</li><li>Select the intended named plan. Since v0.9.21 each Pokémon can keep several named plans, optionally with its own Item Archive.</li><li>Check favorites and attack pairs. The Season 3 plan holds up to eight planned attacks and four favorites. Planned attacks still depend on offers and your unlocked Affinity.</li><li>For an imported code or shared link, use the original game’s build import/share controls. Our planner link and JSON store this website’s draft and cannot be pasted as a native game code.</li></ol>'
        '<p>Season 3 adds <strong>Joins</strong> at Bill’s Machine. Joining keeps the two attacks in one slot but stops their leveling and prevents fusion. The v0.9.17 plan can retain the pair when copied or shared. Choose the intended transformation before accepting it. Check the <a href="/pokebonk/archive/">active Archive and missing-item checklist</a> if a copied item never appears.</p>'
        '<p>Older starter plans below are dated examples. Season 3 rebalanced Gen 1, items and fusions, so their old numerical comparisons cannot establish today’s strongest build.</p>')
    add('lab', 'archive-current', 'Current Archive slots and optional upgrades',
        '<p>Version 0.9.21 changes the item contribution to <strong>one Archive slot per unlocked item</strong>. The current definition still gives five slots per purchased Archive level, up to six levels, and requires at least level one for the item contribution. Older one-per-two examples describe v0.8.55. Use the <a href="/pokebonk/archive/">Archive checklist</a> before planning a new item pool.</p><p>Fully upgraded Lab upgrades can now be disabled. The older calculator retains its reviewed inventory and prices. Check the actual upgrade’s enabled state and current price in game before spending.</p>')
    add('troubleshooting', 'saved-run-current', 'Saved runs, missing captures and iOS loading',
        '<p>Version 0.9.23 reports that saved runs no longer expire after two days or close automatically on return, and recovered captures are retained. If an older guide tells you to finish within two days, update the original client and inspect Continue on the same account before abandoning the run.</p><ol><li>Record the exact host, account or Guest, version and visible error.</li><li>Keep the browser profile that owns the session. Check Continue and wait for its server response.</li><li>For an Expedition still in progress, keep the same browser and avoid starting another run. Version 0.9.17 says the previous Expedition is submitted before another begins.</li><li>If recovery still fails, use Report with mode, map, difficulty, Pokémon and reproduction steps. This guide cannot restore server records.</li></ol><p>Version 0.9.20 changes iPhone/iPad zone-transition memory use and Safari music retries. Check those versions before applying an old workaround. These are developer-reported corrections.</p>')
    add('mobile', 'ios-current', 'iPhone, iPad and controller changes to check',
        '<p>Use the original browser entry on iPhone or iPad and check the displayed version. Version 0.9.20 reports lower-memory zone changes and fewer Safari music retries. Version 0.9.23 makes the controller Back action close an open window.</p><p>If the symptom persists, record device, OS, browser, host and version. Keep the existing profile before comparing another browser. Current Android/Mac app announcements do not establish an iOS app or a tested device-performance guarantee. For an interrupted run, follow the <a href="/pokebonk/troubleshooting/#saved-run-current">saved-run checks</a>.</p>')
    add('updates', 'november-review', 'What v0.9.23 changes for your next run',
        '<p>The original host reported v0.9.23 on November 11. For a copied build, inspect <a href="/pokebonk/builds/#rental">Rental and named plans</a>, then its <a href="/pokebonk/archive/">own Archive</a>. The latest notes add a warning when a plan uses its own Archive and fix archived attacks returning. Completed League challenges now appear in zone order.</p><p>For a saved run, the latest release removes two-day expiration and reports retained captures on recovery. Co-op receives synchronized final hordes, matchmaking that skips already-started rooms and a longer reconnect opportunity. Actual availability and connectivity still require checking the room.</p><p>Season 3 is active. <a href="/pokebonk/great-expedition/">The Great Expedition</a> is scheduled to end November 19 at 17:30 UTC. Its latest loot filter can restrict Shiny equipment by rarity. Johto Daily Mutation rewards accept any Pokémon from v0.9.21, superseding the launch announcement’s Johto-only restriction.</p>')
    add('multiplayer', 'november-coop', 'Current final-horde and reconnect checks',
        '<p>The v0.9.23 notes report the final horde arriving simultaneously for everyone, matchmaking excluding already-started rooms and more time to reconnect. Reload to a matching original version before diagnosing an older symptom. If the warning remains, record each player’s version and the room state.</p><p>Season 3 adds shared map events and team Rifts, with each player choosing a Relic after the Alpha falls. Ranked co-op runs contribute clan points. Personal menu protection, unanimous team-pause voting and a disconnected player remain separate states. No shared run was completed during this review.</p>')
    add('daily-mutation', 'johto-rewards', 'Johto reward eligibility changed',
        '<p>From v0.9.21, Johto Daily Mutation prizes can be earned with <strong>any Pokémon</strong>. The release also says previous wins with Kanto partners receive their rewards. This supersedes the Johto-only launch condition. Open the active mutation, inspect its map/difficulty and reward state, and record an uncredited result before trying another run.</p>')
    add('survival', 'season-three', 'Season 3 survival timing',
        '<p>The Season 3 announcement replaces the older hours-long schedule. Solo overflowing Rifts begin at minute 8. Defeating their Alpha seals them. The minute-15 legendary follows the map, Endless Night starts at 30, Mewtwo arrives at 35 and Apocalypse begins at 40 with increasing difficulty. The Eternal achievement now asks for 45 minutes.</p><p>Check your current mode before following the older schedule below. Rifts are wave-based from v0.9.21, with E calling the next wave early. Use this only when ready for the added pressure. These are announced timings, without a completed survival test.</p>')
    page = pages['/pokebonk/survival/']
    page['html'] = re.sub(r'<p class="answer">.*?</p>', '<p class="answer">Season 3 Survival introduces solo overflowing Rifts from minute 8, the map legendary at 15, Endless Night at 30, Mewtwo at 35 and Apocalypse at 40. Plan your next checkpoint around this schedule. Older v0.8.62 Forest timings below remain historical.</p>', page['html'], count=1, flags=re.S)
    page['html'] = page['html'].replace('<h2>Use the Forest milestone timeline</h2>', '<h2>Historical v0.8.62 Forest timeline</h2><p>This table and diagram record the earlier release. Use the Season 3 schedule above for the current original game.</p>')
    page['html'] = page['html'].replace('<section id="season-three">', '<figure><img src="/assets/pokebonk/forest-1280.webp" width="1280" height="672" loading="lazy" alt="Original PokeBonk forest arena artwork with waterfall and altar"><figcaption>Original forest promotional artwork, an arena illustration. © Charcher / respective rights holders.</figcaption></figure><section id="season-three">', 1)
    add('ko/beginners-guide', 'november-current', '최신 빌드와 저장 문제 확인',
        '<p>2026년 11월 11일 원작 v0.9.23을 확인했습니다. Builds → Rental 또는 빌드 계획의 Rent에서 다른 트레이너의 빌드를 복사할 수 있습니다. 제작자, 순위와 부족한 조건을 확인한 뒤 사용할 계획을 선택하세요. 여러 이름의 계획과 계획별 아이템 Archive를 구분해야 합니다.</p><p>v0.9.23 공지는 저장한 전투의 이틀 만료와 복귀 시 자동 종료를 수정하고, 복구한 포획을 보존한다고 설명합니다. 기존 브라우저와 계정을 유지하고 Continue 응답을 확인하세요. 설치·복구·실제 기기 성능은 시험하지 않았습니다.</p><p>대원정은 11월 19일 17:30 UTC 종료 예정입니다. <a href="/pokebonk/great-expedition/">철수와 장비 보관 안내 (영어)</a>를 확인하세요. 조토 일일 변이 보상은 v0.9.21부터 모든 포켓몬으로 받을 수 있습니다.</p>')

    old_date, old_version = ctx['DATE'], ctx['VERSION']
    ctx['DATE'], ctx['VERSION'] = 'November 11, 2026', 'v0.9.23'
    sources = [(SOURCE, 'Original v0.9.23 definitions and release history', 'Checked November 11, 2026. SINGLE_SOURCE; announced rules and public code.'), (NEWS, 'Charcher’s project announcements', 'Season 3, Expedition and Archive descriptions. Older statements are superseded where noted.')]
    ctx['article']('archive', 'PokeBonk Archive Guide: Slots, Templates & Missing Items', 'Set the right Archive for your build',
        'Check PokeBonk Archive slots, named-plan item pools and missing-item warnings using the reviewed v0.9.23 rules.',
        'Open Lab → Items to review your archived items, then select the build plan you intend to use. An archived item is excluded from Poké Ball and shop offers. In v0.9.21 the item contribution became one slot per unlocked item. Check the active plan before changing the pool.', [
        ('slots', 'Calculate slots with the current rule', '<p>The v0.9.23 definition gives <strong>5 × purchased Archive level + unlocked eligible item count</strong>, with the item contribution enabled only after buying at least level one. The upgrade has six levels. Level zero supplies zero slots. Level one with ten unlocked eligible items supplies 15 slots, and level three with 21 supplies 36. These are arithmetic examples.</p><p>The old rule added one slot per two items. Its historical 59-slot maximum is unsuitable for the current roster. Read the live counter before buying a level. Our <a href="/pokebonk/lab/">Lab calculator</a> retains an older reviewed inventory.</p>'),
        ('plan', 'Check a copied build before a run', '<ol><li>Choose the Pokémon and named plan in Builds. Inspect missing and locked choices.</li><li>Check whether that plan has its own Item Archive. Version 0.9.21 introduced this option. Version 0.9.23 adds an explicit warning for it.</li><li>Compare every wanted item with that Archive. Return a wanted item to the pool before beginning a new run.</li><li>Review type-item filters in the Build Plan, introduced in v0.9.19. They can travel with a shared build without changing the Lab Archive.</li><li>Check the attack Archive separately. Season 3 allows per-Pokémon attack exclusions while preserving at least twelve attacks. The latest notes fix archived attacks returning.</li></ol>'),
        ('templates', 'Keep templates and saved runs consistent', '<p>Season 3 expands item Archive templates to twelve across four pages. Use a recognizable name for each purpose. Compare a recovery-oriented plan and a damage plan with the same Pokémon, difficulty and upgrades before deciding which pool helps you.</p><p>The v0.8.81 rule preserves the Archive that a saved run already had. Changing the pool before Continue affects a new run. Version 0.8.85 announces account-backed build plans and Archive templates. Check the same original account when switching devices.</p>'),
        ('missing', 'When the item you want never appears', '<p>Inspect unlock state, active plan, its own Archive, Lab template, type filters and whether you resumed an older run, in that order. A correct pool still offers random choices. It cannot promise that a particular item appears on the next roll.</p><p><img src="/assets/pokebonk/iteration/archive-icon.png" width="30" height="30" alt="Everstone icon used by the original game for the Archive Lab upgrade" loading="lazy"> The original Archive upgrade uses this Everstone icon. Game asset from Charcher’s v0.9.23 public asset bundle, inspected November 11.</p>')], sources,
        [('builds/#rental', 'Inspect a Rental build'), ('lab/', 'Budget permanent upgrades'), ('items-vitamins/', 'Check item effects')])
    ctx['article']('great-expedition', 'PokeBonk Great Expedition Guide: Extract & Keep Your Loot', 'Leave the Great Expedition with your loot',
        'Plan PokeBonk Great Expedition extraction, safe-pocket and insurance decisions, with current event dates and v0.9.23 recovery checks.',
        'Enter the Great Expedition from the original menu, locate an available extraction and hold its circle for 15 seconds for Pidgeot. Preserve valuable loot before taking extra fights. Checked November 11, the live status schedules the event through November 19, 2026 at 17:30 UTC.', [
        ('first-extract', 'Plan your first successful extraction', '<ol><li>Open the original event tile and inspect its entry equipment, timer and extraction indicators.</li><li>Choose equipment you can afford to risk. The mode uses four gear slots and Valley Tokens. Check gear cards before replacing an equipped item.</li><li>Locate loot and a route back to extraction. Rocket crates and Ancient Chambers are announced sources. Trainer echoes may attack or avoid you, so keep a retreat route.</li><li>Move to an available extraction circle and hold it for 15 seconds. The announcement describes six extraction windows over a run.</li><li>Inspect the result screen and returned inventory before starting another Expedition.</li></ol><p>The run reaches Red Night at minute 20 and collapse at 25. For a first extraction, favor an earlier available exit over carrying more loot into Red Night. This is a risk-management recommendation.</p>'),
        ('protect', 'Choose what to protect before entering', ctx['table'](['Decision', 'What the source establishes', 'Practical check'], [('Safe pocket', 'Carried loot is lost on defeat except protected pocket contents.', 'Store what you most want to preserve before taking another risk.'), ('Insurance', 'Costs 30% of gear value on entry and returns insured gear with wear after defeat.', 'Check the marked insured items and affordability before entering.'), ('Escape Rope', 'The announcement describes extraction at any time.', 'Check the actual available consumable and confirmation. No use was tested here.'), ('Repair or reforge', 'Bill’s PC offers repair, reforge and recycling.', 'Read the cost and selected affix. v0.9.17 says reforge changes only the selected affix.')]) + '<p>Seals track event rewards. Valley Tokens pay for this mode’s services. Check the Seal Book separately from the value of equipment in your bag.</p>'),
        ('filters', 'Sort loot without losing track of equipped gear', '<p>Version 0.9.21 adds level, Legendary and Shiny equipment filters and bulk selling. Version 0.9.23 adds a Shiny-gear rarity filter with all, Epic+ and Legendary-only options. Inspect the selected filter when expected loot seems absent. Read the selected sale inventory before confirming a bulk action.</p><p>Version 0.9.20 reports clearer insured-gear and extraction UI. Version 0.9.17 gives opened extraction its own map icon. Check the current map marker instead of relying on an older screenshot.</p>'),
        ('recover', 'If the Expedition remains in progress', '<p>The v0.9.14 instruction is to return in the same browser without starting another run. Version 0.9.17 says the game submits the previous Expedition before another begins. Preserve that session and record the exact error if it still fails. The v0.9.23 saved-run corrections remove two-day expiration and preserve recovered captures. These are release statements, without a successful recovery test.</p>'),
        ('schedule', 'Use the current event end time', '<p>The original announcement still contains November 25. The later v0.9.2 correction, November news and the live status endpoint agree on <strong>November 19 at 17:30 UTC</strong> (18:30 in Spain, November 20 at 01:30 in China). The November 11 status marks the Expedition live and claimable. Its definition allows fourteen further days for claims, subject to server changes. A claim period does not extend the play window.</p><p>The event art below comes from the original game’s event assets. It depicts Pidgeot and the Wild Valley and is promotional artwork.</p>')],
        sources + [('https://api.pokebonk.com/status', 'Original live event status', 'Sampled November 11. Event availability and end time can change.')],
        [('troubleshooting/#saved-run-current', 'Check an interrupted run'), ('builds/', 'Plan a loadout'), ('updates/#november-review', 'Read current changes')])
    p = pages['/pokebonk/great-expedition/']
    p['html'] = re.sub(r'<figure>.*?</figure>', '<figure><img src="/assets/pokebonk/iteration/expedition.webp" width="1280" height="720" alt="Original Great Expedition artwork showing Pidgeot above the Wild Valley and an Ancient Chamber" loading="lazy"><figcaption>Great Expedition promotional artwork from the original game, inspected November 11, 2026. © Charcher / respective rights holders.</figcaption></figure>', p['html'], count=1, flags=re.S)
    p['html'] = p['html'].replace('https://megabonk.org/assets/pokebonk/forest-1280.webp', 'https://megabonk.org/assets/pokebonk/iteration/expedition.webp')
    # The Archive object image supplies the page-specific visual. Remove the generic forest.
    p = pages['/pokebonk/archive/']
    p['html'] = re.sub(r'<figure>.*?</figure>', '', p['html'], count=1, flags=re.S)
    p['html'] = p['html'].replace('https://megabonk.org/assets/pokebonk/forest-1280.webp', 'https://megabonk.org/assets/pokebonk/iteration/archive-icon.png')
    home = pages['/pokebonk/']
    home['html'] = home['html'].replace('<section class="section" id="guides">', '<section class="section prose" id="season-three"><h2>Season 3 tasks</h2><p><a href="/pokebonk/great-expedition/">Extract from the Great Expedition</a> · <a href="/pokebonk/archive/">Set your Archive</a> · <a href="/pokebonk/builds/#rental">Copy and check a Rental build</a></p><p>Checked November 11, v0.9.23. The event is scheduled through November 19 at 17:30 UTC. Older numerical guides retain their dated snapshots.</p></section><section class="section" id="guides">', 1)
    ctx['DATE'], ctx['VERSION'] = old_date, old_version
